import re,os,subprocess,html,json,datetime
from PIL import Image
H=os.path.dirname(os.path.abspath(__file__)); R=os.path.dirname(H)
FD=os.environ.get("FONTDIR","/usr/share/fonts/opentype/inter")
CAPA="data:image/jpeg;base64,"
BASE="https://raw.githubusercontent.com/gustavobaronidog-ctrl/separago-marketing/main/midia"
BAG='<svg viewBox="0 0 100 100" width="120" height="120"><circle cx="50" cy="50" r="50" fill="#FF8A00"/><path d="M33 40 C33 22 67 22 67 40" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round"/><path d="M27 38 H73 L77 74 Q77.5 80 71 80 H29 Q22.5 80 23 74 Z" fill="#fff"/><path d="M40 56 L47 63 L61 49" fill="none" stroke="#FF8A00" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/></svg>'
BG={"foto1":("rgba(10,10,10,.72),rgba(10,10,10,.82)","auto 100%","8% 50%"),"foto2":("rgba(60,25,0,.72),rgba(10,10,10,.85)","auto 130%","90% 30%"),"foto3":("rgba(0,35,30,.70),rgba(5,15,15,.86)","auto 160%","45% 60%"),"foto4":("rgba(20,20,60,.68),rgba(5,5,20,.86)","auto 200%","15% 85%")}
def page(txt,i,n,bg,cta):
    d=bg is not None; fg="#fff" if d else "#0b0b0b"; mu="rgba(255,255,255,.65)" if d else "#777"; hl="#FF8A00" if d else "#FFC53D"
    t=re.sub(r"\*\*(.+?)\*\*",r'<span class="h">\1</span>',html.escape(txt))
    off="rgba(255,255,255,.3)" if d else "#ddd"
    bars="".join('<i style="background:%s"></i>'%(fg if k<i else off) for k in range(n))
    if d:
        g,sz,pos=BG[bg]
        bgc="background-color:#111;background-image:linear-gradient(0deg,%s),url(%s);background-size:100%% 100%%,%s;background-position:0 0,%s;"%(g,CAPA,sz,pos)
    else: bgc="background:#fff;"
    btn='<div class="b">Link na bio →</div>' if cta else ""
    right="" if cta else "<span>deslize →</span>"
    fs=86 if len(txt)<90 else 72
    return f'''<html><head><meta charset="utf-8"><style>
@font-face{{font-family:I;src:url(file://{FD}/Inter-Black.otf);font-weight:900}}
@font-face{{font-family:I;src:url(file://{FD}/Inter-Bold.otf);font-weight:700}}
@font-face{{font-family:I;src:url(file://{FD}/Inter-SemiBold.otf);font-weight:600}}
*{{margin:0;box-sizing:border-box}}body{{width:1080px;height:1350px;font-family:I,'Noto Color Emoji';color:{fg};{bgc}position:relative}}
.bars{{position:absolute;left:96px;right:96px;top:68px;display:flex;gap:12px}}.bars i{{flex:1;height:6px;border-radius:3px}}
.who{{position:absolute;left:96px;top:250px;display:flex;align-items:center;gap:30px}}.who b{{display:block;font-size:46px;font-weight:700}}.who s{{text-decoration:none;font-size:40px;color:{mu};font-weight:600}}
.t{{position:absolute;left:96px;right:96px;top:440px;font-size:{fs}px;font-weight:900;line-height:1.12;letter-spacing:-2px}}
.h{{background:linear-gradient({hl},{hl}) 0 88%/100% 38% no-repeat}}
.f{{position:absolute;left:96px;right:96px;bottom:90px;display:flex;justify-content:space-between;font-size:34px;font-weight:700;color:{mu}}}
.b{{position:absolute;left:96px;top:1010px;background:{"#FF8A00" if d else "#0b0b0b"};color:#fff;font-size:44px;font-weight:700;padding:30px 44px;border-radius:60px}}
</style></head><body><div class="bars">{bars}</div><div class="who">{BAG}<div><b>SeparaGo</b><s>@separa.go</s></div></div><div class="t">{t}</div>{btn}<div class="f"><span>{i:02d} / {n:02d}</span>{right}</div></body></html>'''
T="/tmp/sgb"; os.makedirs(T,exist_ok=True)
FP=R+"/fila/fila.json"
try: fila=json.load(open(FP))
except Exception: fila=[]
ids={x["id"] for x in fila}
d0=datetime.date(2026,11,10)
for ci,(slug,bg,sl,leg,tags) in enumerate(C,1):
    out=f"{R}/midia/c{ci:02d}"; os.makedirs(out,exist_ok=True); urls=[]
    for si,tx in enumerate(sl,1):
        h=f"{T}/c{ci:02d}_{si}.html"; p=f"{T}/c{ci:02d}_{si}.png"
        open(h,"w").write(page(tx,si,len(sl),bg if si==1 else None,si==len(sl)))
        subprocess.run(["google-chrome","--headless=new","--no-sandbox","--disable-gpu","--allow-file-access-from-files","--hide-scrollbars","--window-size=1080,1350","--screenshot="+p,"file://"+h],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=120)
        Image.open(p).convert("RGB").save(f"{out}/{si}.jpg",quality=90); urls.append(f"{BASE}/c{ci:02d}/{si}.jpg")
    iid=f"c{ci:02d}-{slug}"; k=ci-1
    if iid not in ids: fila.append({"id":iid,"data":(d0+datetime.timedelta(days=k//2)).isoformat(),"hora":"12:00" if k%2==0 else "19:00","tipo":"carrossel","legenda":leg+"\n\n"+tags,"imagens":urls,"status":"pendente"})
os.makedirs(R+"/fila",exist_ok=True); json.dump(fila,open(FP,"w"),ensure_ascii=False,indent=1)
print("ok",len(fila))
